# Read grid from file
with open('/workdir/data/input.txt', 'r') as f:
    lines = [line.strip() for line in f.readlines() if line.strip()]

# Grid is 5 rows x 10 columns
grid = []
for line in lines:
    # Parse each character in the line
    row = []
    for char in line:
        if char == 'O':
            row.append(False)  # Blocked
        else:
            row.append(True)   # Allowed (X)
    grid.append(row)

print(f"Grid shape: {len(grid)} x {len(grid[0])}")
print("Grid content (True=X, False=O):")
for i, row in enumerate(grid):
    print(f"Row {i}: {[ 'X' if r else 'O' for r in row]}")
