# Parse grid properly
with open('/workdir/data/input.txt', 'r') as f:
    content = f.read()

lines = content.strip().split('\n')
grid = []

for line in lines:
    # Remove all whitespace
    line_clean = ''.join(line.split())

    # Create row
    row = []
    for char in line_clean:
        if char == 'O':
            row.append(False)  # Blocked
        else:
            row.append(True)   # Allowed (X)

    grid.append(row)

# Find all X cells
all_x_cells = []
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if grid[r][c] == True:
            all_x_cells.append((r, c))

print(f"Grid dimensions: {len(grid)} x {len(grid[0])}")
print(f"Total X cells: {len(all_x_cells)}")
